#cpms-device-state.dark .state-alarm,
#cpms-device-state.dark .state-lockout,
#cpms-device-state.dark .availability-unavailable,
#cpms-device-state.dark .quality-missing,
#cpms-device-state.dark .quality-bad { color: #ff7383; background: rgba(242, 73, 92, 0.2); }
#cpms-device-state.dark .event-trip { background: #c4162a; color: #ffffff; }
